    "content": "2026年09月25日 9月24日，国务院新闻办举行新闻发布会，交通运输部新闻发言人、副部长李扬等介绍了中秋、国庆假期交通运输服务保障有关情况。 “今年中秋、国庆假期间隔3个工作日，一些公众会调整为13天超长假期，带来出行量和出行方式的新变化。”李扬介绍，交通运输各部门多措并举，全力确保假期平安顺畅出行。 经研判，中秋假期客流会呈现温和增长，国庆假期出行会高位运行，“两节”假期期间全社会跨区域人员流动量预计分别达6.5亿人次、21.3亿人次。 “根据分析，国庆假期的平均新能源车流量，是平时的1.6倍以上。国庆首日将…"
