    "content": "2026年09月25日 消费，一头连着百姓民生，一头连着经济发展。 “坚持内需主导，建设强大国内市场”是今年经济工作的重点任务之首。习近平总书记强调：“统筹促消费和扩投资，用好我国超大规模市场优势”“适应消费结构变化，扩大优质商品和服务供给”。 近日，新华社记者随2026年“活力中国调研行”主题采访活动赴湖南、福建、山东等地，从古厝民宿到海洋牧场，从首发首店到夜间市集，品味消费转型升级中的活力中国，感受超大规模市场的万千气象。 结合采访情况，新华社9月24日推出第三十七期“中国经济圆桌会”大型全媒体访谈节目，邀请商…"
