    "description": "2026年09月25日 望月怀远 唐·张九龄 海上生明月，天涯共此时。 情人怨遥夜，竟夕起相思。 灭烛怜光满，披衣觉露滋。 不堪盈手赠，还寝梦佳期。 自初唐张若虚《春江花月夜》之后，游子月夜相思逐渐成为唐代诗歌咏唱的一个主题。张九龄此诗的“海上生明月，天涯共此时”，显然是从张若虚的“春江潮水连海平，海上明月共潮生”“谁家今夜扁舟子？何处相思明月楼”中演化而来。一个“共”字带出“情人怨遥夜，竟夕起相思”。长夜漫漫，月圆，人却未能团圆，怎能…",
    "content": "2026年09月25日 望月怀远 唐·张九龄 海上生明月，天涯共此时。 情人怨遥夜，竟夕起相思。 灭烛怜光满，披衣觉露滋。 不堪盈手赠，还寝梦佳期。 自初唐张若虚《春江花月夜》之后，游子月夜相思逐渐成为唐代诗歌咏唱的一个主题。张九龄此诗的“海上生明月，天涯共此时”，显然是从张若虚的“春江潮水连海平，海上明月共潮生”“谁家今夜扁舟子？何处相思明月楼”中演化而来。一个“共”字带出“情人怨遥夜，竟夕起相思”。长夜漫漫，月圆，人却未能团圆，怎能不起相思？“灭烛怜光满，披衣觉露滋”，“怜”即爱也，因“怜光满”而灭烛披衣，步出…"
