    "description": "2026年09月25日 《长征日记》选摘 当代·萧 锋 九月十二日 晴 晨出发，经巴拉奠、岸哇、纳告到阿夏乡宿营，行程八十里。 每到中秋，我总会想起父亲萧锋《长征日记》里的一页。 1935年9月12日，农历八月十五。父亲在日期后面只写了一个“晴”字，接着便是：“晨出发，经巴拉奠、岸哇、纳告到阿夏乡宿营，行程八十里。”没有月亮，没有月饼，也没有一句思乡的话。 八月十五，行程八十里。这9个字总让我停留很久。中秋是团圆的日子，可那一年的中秋，…",
    "content": "2026年09月25日 《长征日记》选摘 当代·萧&nbsp;&nbsp;锋 九月十二日&nbsp;&nbsp;晴 晨出发，经巴拉奠、岸哇、纳告到阿夏乡宿营，行程八十里。 每到中秋，我总会想起父亲萧锋《长征日记》里的一页。 1935年9月12日，农历八月十五。父亲在日期后面只写了一个“晴”字，接着便是：“晨出发，经巴拉奠、岸哇、纳告到阿夏乡宿营，行程八十里。”没有月亮，没有月饼，也没有一句思乡的话。 八月十五，行程八十里。这9个字总让我停留很久。中秋是团圆的日子，可那一年的中秋，父亲和战友们刚走出茫茫草地，饥饿和疲…"
