    "pub_date": "2026-09-25 07:26:28",
    "author": "乔本孝",
    "description": "新华社巴黎9月24日电（记者乔本孝）法国总统马克龙24日说，法国将派兵保护沙特阿拉伯西海岸延布港的石油设施免受也门胡塞武装袭击，以稳定石油供给、控制油价上涨。 马克龙在接受两家法国电视台联合采访时说，法国已与沙特完成相关讨论，法方将派出士兵并部署雷达、防御系统等军事力量，同时视局势变化调动驻扎在中东地区的空军力量。他强调，此举是为了保护延布的石油设施，而不是参与相关冲突。 近期，也门胡塞武装与支持政府军的沙特之间冲突持续升级，已多次袭击…",
