    "content": "新华社伊斯兰堡9月25日电（记者杨恺）巴基斯坦军方消息人士24日说，巴安全部队当天夜间在该国西南部俾路支省古利斯坦地区击毙数名来自阿富汗的武装分子。 该消息人士说，巴安全部队与武装分子仍在间歇性交火，巴安全部队将在边境地区保持高度警戒，随时准备对任何从阿富汗侵入巴基斯坦领土的行为作出及时有效回应。 阿富汗政府发言人穆贾希德24日在社交媒体发表声明说，巴基斯坦军方当天凌晨对阿富汗3个省发动空袭，造成至少4人死亡。 声明说，袭击波及阿富汗东部帕克蒂亚省、霍斯特省以及南部坎大哈省，这3个省均与巴基斯坦接壤，阿政府将对“野…"
