    "content": "新华社日内瓦9月24日电（记者焦倩）联合国贸易和发展会议24日发布报告说，巴勒斯坦经济和公共财政面临严峻压力，加沙地带恢复和重建所需资金预计达715亿美元。 报告指出，以色列的长期占领制约巴勒斯坦经济发展，自2023年10月新一轮巴以冲突爆发以来，占领带来的经济代价大幅上升。 巴勒斯坦国内生产总值（GDP）在2024年大幅收缩后，2025年增长4.3%，但仍比2022年水平低20%。自2023年10月以来，巴勒斯坦被占领土已有数十万个工作岗位流失，累计劳动收入损失估计达28亿美元。 报告指出，约旦河西岸的流离失所现…"
