    "content": "当地时间9月15日，日本厚劳省在发布会上宣布： 日本百岁以上老人数量较上一年增加7914人，达到107677人。这是有统计以来，日本百岁老人首次突破10万。[1] 论总量，日本在世的百岁以上老人不如中国，但论人口比例，日本的百岁老人密度已经达到87.51/10万，领先全球。 对于这两年异常火爆的长寿圈来说，这是个值得关注的现象： 为什么日本百岁老人比例能全球第一？他们有什么特点？对于中国来说，到底有什么值得借鉴和规避的经验教训？ 历史的进程日本厚劳省大臣上野贤一郎在当天的发布会上表示，日本百岁老人破10万，背后是“…"
