    "content": "新华社科威特城9月24日电（记者尹炣）萨那消息：也门胡塞武装军事发言人叶海亚·萨雷亚24日称，该组织当天使用数十枚弹道导弹和无人机，对沙特阿拉伯西南部吉赞地区多处军事目标发动大规模袭击。 萨雷亚当天在该组织控制的马西拉电视台发表声明称，此次行动打击了多处指挥控制中心、武器库和部队集结地，包括沙特部队“第六应急师”的指挥所。袭击“造成数百人死伤”，其中包括沙特“增援部队中的也门和苏丹人员，以及数十名沙特士兵和军官”。 声明称，此次行动是为应对“沙特在边境地区大规模集结兵力、意图升级的敌对行动”。 沙特方面暂未就此作出…"
