    "content": "24/09/2026 - 17:49 阿联酋周四暂停了伊朗航空公司的所有航班，以遵守美国针对伊朗航空业的制裁；此前，周三已有前往其他目的地的多趟航班被取消。 据伊斯纳Isna通讯社周四报道：“自午夜起，伊朗各航空公司飞往阿联酋的所有航班均已被取消”。 据法新社从一名乘客处获悉，伊朗航空旅游公司（Iran Airtour）一班飞往迪拜的航班于上午在德黑兰即将起飞前被取消，而当时乘客们已持有机票。 迪拜曾是伊朗航空公司在中东最重要的目的地，每天有多班航班从伊朗起飞前往该地。 迪拜机场通往欧洲、亚洲和非洲，常被伊朗旅客用…"
