    "content": "我之前半年，开发个人项目的时候一直在用 Linear 来进行项目管理。本来我以为免费配额是够用的，但最近几个月，我同时开发多个项目，Issue 就多了起来，Linear 的免费配额就不够用了，因此，我就转向了 GitHub Projects ，毕竟这些项目的代码本来就托管在 GitHub 上。 迁移到 GitHub Projects 之后，我发现它内置的 PR 与 Issue 联动工作流不如 Linear 完善，也不太符合我的需求。比如，当我给一个 Issue 关联 Draft PR 时，我希望这个 Issue 的…"
