    "content": "25 年年底，我当时还在上班，有一天领导让我接手一个我不了解的项目，上来就要改接口，于是就有了用抓包工具从 app 端抓包看涉及的功能都调用了哪些接口，这才有了后续我们做抓包工具的灵感，后来我想用到一些功能但试了几款都没有，就更想自己做一款了。 25 年我在 app store 看到的抓包工具还不到十款吧（现在再去看就多了），基本长得都差不多，功能也差不多，体验也差不多。一看就知道都是基于开源的版本改的。 我感觉这是个机会吧，虽然是小众需求，但能选择的产品不多，而且现有产品也不好用，于是就想开发一款比现有产品都好用…"
